    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configure as definições de todo o sistema: URL base, segurança, idioma padrão, fuso horário, valores padrão de pontuação de risco e muito mais.',
    'SettingsPreferencesDesc'             => 'Valores padrão e preferências de comportamento em todo o SimpleRisk: idioma, fuso horário, estados de auditoria, requisitos de mapeamento de riscos, opções de comportamento da interface e semelhantes.',
    'SettingsFileUploadDesc'              => 'Tipos de ficheiros permitidos para upload e limites de tamanho para os vários campos de anexos.',
    'SettingsMailDesc'                    => 'Configuração SMTP para notificações de e-mail enviadas, incluindo transporte, anfitrião, autenticação e endereço de resposta.',
    'SettingsBackupsDesc'                 => 'Configure a retenção, o agendamento e as ligações de download dos backups da base de dados do SimpleRisk.',
    'SettingsSecurityDesc'                => 'Definições de autenticação, sessão, política de palavras-passe, URL base e segurança da API.',
    'SettingsLoggingDesc'                 => 'Configuração do registo de depuração e auditoria: níveis de registo, retenção e localização dos ficheiros de registo.',
    'HealthCheckDesc'                     => 'Diagnostique o estado do sistema: versão do PHP, extensões, permissões de arquivos, conectividade da base de dados, agendamento do cron e ativações de Extras.',
    'AnnouncementsDesc'                   => 'Redija e gira avisos em banner visíveis para todos os usuários.',
    'RegisterAndUpgradeDesc'              => 'Registe a sua instalação do SimpleRisk, introduza ou renove uma chave de subscrição e inicie atualizações do Core/Extras com um só clique.',
    'QueueMonitorDesc'                    => 'Inspecione a fila de tarefas em segundo plano: tarefas pendentes, em curso e com falhas.',
    'ExtrasDesc'                          => 'Ative, desative e configure os Extras do SimpleRisk (módulos adicionais pagos).',
    'ArtificialIntelligenceExtraDesc'     => 'O Extra de Inteligência Artificial proporciona uma análise de riscos melhorada (incluindo avaliações FAIR) e documentação personalizada.',
    'CustomizationExtraDesc'              => 'O Extra de Personalização permite adicionar e remover diferentes tipos de campos e criar dinamicamente modelos de página personalizados.',
    'NotificationExtraDesc'               => 'O Extra de Notificações por E-mail permite ao SimpleRisk enviar notificações por e-mail quando os riscos são submetidos, modificados ou alvo de outras ações. Este Extra também pode ser adicionado como um script agendado para enviar lembretes periódicos quando os riscos estão prontos para uma revisão de gestão. No produto SimpleRisk Core, sem este Extra, não é comunicada nenhuma notificação fora da própria ferramenta.',
    'VulnerabilityManagementExtraDesc'    => 'O Extra de Gestão de Vulnerabilidades permite aos clientes integrar a sua instância do SimpleRisk com o Qualys, o Tenable.io ou o Rapid7 Nexpose/InsightVM e importar para o SimpleRisk dados de ativos e de vulnerabilidades. A partir daí, pode selecionar os sites que pretende cobrir, determinar que pontuações de vulnerabilidade devem ser importadas e fazer a triagem das vulnerabilidades que se transformam em riscos para as acompanhar.',
    'IncidentManagementExtraDesc'         => 'A funcionalidade adicional de Gestão de Incidentes baseia-se no guia NIST 800-61 sobre o tratamento de incidentes de segurança informática e oferece funcionalidades de gestão de incidentes diretamente no sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Renomeie a terminologia do SimpleRisk (Risco, Ativo, Estrutura, etc.) em toda a interface do utilizador.',
    'RiskConfigurationDesc'               => 'Configure as regras de pontuação de risco: níveis, apetite, limiares de SLA e as fórmulas de risco clássica / de fatores contributivos.',
    'RiskAndThreatCatalogDesc'            => 'Mantenha o catálogo de valores de risco e ameaça utilizados nas listas suspensas.',
    'AddAndRemoveValuesDesc'              => 'Gira os valores das listas pendentes dos campos de risco: localização, origem, categoria, equipa, tecnologia e muito mais.',
    'AssetValuationDesc'                  => 'Configure a escala de valorização de ativos e as substituições de valorização por ativo.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Adicionar, editar, desativar e repor utilizadores; gerir política de senhas.',
    'RoleManagementDesc'                  => 'Defina as funções e as permissões que cada função concede.',
    'TeamManagementDesc'                  => 'Criar e gerir equipas utilizadas para filtragem de visibilidade de registos.',
    'SeparationExtraDesc'                 => 'A funcionalidade adicional de Separação Baseada em Equipa restringe a visualização de riscos apenas aos utilizadores que são membros da equipa à qual o risco está atribuído. No produto SimpleRisk Core, sem esta funcionalidade adicional, todos os utilizadores podem visualizar todos os riscos.',
    'CustomAuthenticationExtraDesc'       => 'A funcionalidade adicional de Autenticação Personalizada suporta a autenticação do Active Directory e SAML. No produto SimpleRisk Core, sem esta funcionalidade adicional, a única opção é criar novos utilizadores no repositório de identidades do SimpleRisk.',
    'EncryptionExtraDesc'                 => 'O Extra de Base de Dados Encriptada gera uma chave de encriptação AES-256 bits aleatória e usa-a para encriptar texto sensível antes de ser inserido na base de dados do SimpleRisk. Isto impede que alguém consiga ver ou modificar os dados sem usar diretamente a aplicação SimpleRisk.',
    'OrganizationManagementDesc'          => 'O Extra de Hierarquia Organizacional permite definir várias unidades de negócios, que podem incluir qualquer número de equipas. Os usuários podem depois ser atribuídos a uma ou mais equipas de várias unidades de negócios. Isto afeta a capacidade de um usuário ver e usar as equipas, os usuários e os ativos aos quais não está associado.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Elimine riscos em massa. Use com moderação — as eliminações são permanentes.',
    'AuditTrailDesc'                      => 'Pesquise e exporte o registo de auditoria do sistema com as ações do utilizador.',
    'ImportExportExtraDesc'               => 'O Extra de Importação-Exportação permite importar dados para o SimpleRisk através do mapeamento de campos de um arquivo CSV para campos da base de dados do SimpleRisk. Pode ser usado para importar resultados de auditoria de uma folha de cálculo de terceiros, resultados de análises de vulnerabilidades de outra ferramenta, ativos da sua CMDB e muito mais. O Extra também permite exportar arquivos CSV do SimpleRisk com riscos, mitigações, revisões ou um relatório combinado dos três.',
    'JiraExtraDesc'                       => 'A funcionalidade Jira Integration Extra oferece aos utilizadores a capacidade de se integrarem bidirecionalmente com uma instância do Jira. Permite ligar riscos a tarefas do Jira, bem como sincronizar os seus dados, estado e comentários.',
    'APIExtraDesc'                        => 'A API Extra permite que os clientes utilizem uma API RESTful para criar interações programadas com outras aplicações, obtendo automatização avançada e aproveitando a infraestrutura existente.',
    'AdvancedSearchExtraDesc'             => "A Pesquisa Avançada Extra transforma a caixa de pesquisa da barra superior numa pesquisa única que abrange riscos, estruturas, controlos, documentos, exceções, testes, auditorias, ativos e grupos de ativos, com uma página de Pesquisa completa para analisar os resultados. Apenas apresenta os registos que o utilizador tem permissão para visualizar.",
    'AssessmentsExtraDesc'                => 'A funcionalidade Avaliação de Riscos Extra permite aos utilizadores definir contactos, criar perguntas (incluindo lógica), combinar várias perguntas com um modelo de questionário, criar questionários e enviá-los para contactos, visualizar os resultados dos questionários, adicionar riscos com base nesses resultados e comparar os resultados ao longo do tempo, importar e exportar avaliações personalizadas externamente e rever o histórico de auditoria da avaliação de riscos.',
    'ActiveAssessmentsDesc'               => 'Veja e gira as avaliações atualmente em curso.',
    'WorkflowsExtraDesc'                  => 'O Extra de Fluxos de Trabalho fornece um motor de fluxos de trabalho visual, orientado por eventos, que automatiza ações de gestão de risco em resposta a eventos no SimpleRisk. Pode criar fluxos de trabalho acionados por alterações — como um risco ser submetido, atualizado ou revisto — para encaminhar aprovações, atribuir trabalho e manter o seu processo em andamento sem intervenção manual.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "O Secure Controls Framework (SCF) Extra é uma integração direta entre o Secure Controls Framework e o SimpleRisk. Importa o catálogo de controlos do SCF e os seus mapeamentos numa vasta gama de estruturas de conformidade e cibersegurança para a funcionalidade de Governação do SimpleRisk, permitindo-lhe adotar as estruturas de que necessita e gerir os seus controlos sem ter de os criar manualmente.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migre colunas legadas de datas de revisão do tipo varchar para tipos de data adequados. Visível apenas quando necessário.',
    'DatabaseUpgradeDesc'                 => 'Acione manualmente a rotina de atualização da base de dados do SimpleRisk.',

