    'Placement' => 'Posicionamento',
    'OwnershipAndMaturity' => 'Responsabilidade e maturidade',
    'MappingsAndGuidance' => 'Mapeamentos e orientações',
    'DeleteFrameworkTitle' => 'Eliminar a estrutura \'{$name}\'?',
