    'Excluded' => 'Excluídos',
    'FwInScope' => 'No âmbito',
    'FwLastTestPassed' => 'Último teste aprovado',
    'FwLastTestFailed' => 'Último teste reprovado',
    'FwNoEvidence' => 'Aplicável, sem evidência',
    'FwMaturityUnderDesired' => 'Maturidade abaixo da desejada',
