    'EnableCSPHelp' => 'A Política de Segurança de Conteúdo (CSP) restringe o navegador de modo a carregar scripts, estilos, imagens e tipos de letra apenas do próprio SimpleRisk, e bloqueia a incorporação de páginas em frames e os envios de formulários entre origens diferentes. É a defesa integrada mais robusta contra cross-site scripting. Mantenha ativada, a menos que entre em conflito com um proxy, uma extensão do navegador ou uma integração de terceiros no seu ambiente.',
    // Define Control Frameworks' Columns picker (Task: Columns picker + saved layout/filters) -- the "Standard" group label above its built-in fields (Family/Owner/Maturity/Status/Class/Phase/Priority/Type); 'CustomFields' already exists.
