    'AssetScoring' => 'Pontuação de ativos',
    'AssetScoringSettingsHint' => 'Cada ativo é classificado como Baixo, Moderado ou Alto quanto à confidencialidade, integridade e disponibilidade, e a confidencialidade pode em alternativa ser Não aplicável, o que a exclui de ambos os resultados. A sua categorização FIPS é a mais elevada das três classificações. A sua pontuação ponderada é a média ponderada dos três valores de nível, e os limiares das faixas convertem essa pontuação numa faixa Baixa, Moderada ou Alta. A alteração destas definições recalcula imediatamente a pontuação de todos os ativos.',
    'Weights' => 'Pesos',
    'AssetScoringWeightsHint' => 'Quanto cada objetivo conta na pontuação ponderada: de 0 a 100, com até duas casas decimais. Uma ponderação de 0 exclui esse objetivo. A integridade e a disponibilidade não podem ser ambas 0, porque uma confidencialidade Não aplicável é sempre excluída.',
    'LevelValues' => 'Valores de nível',
    'AssetScoringLevelValuesHint' => 'O número que cada classificação contribui para a pontuação ponderada: superior a 0 e até 100, com até duas casas decimais, sendo Baixo inferior a Moderado e Moderado inferior a Alto. Os valores padrão são Baixo 1, Moderado 2 e Alto 3.',
    'BandThresholds' => 'Limiares das faixas',
    'AssetScoringBandThresholdsHint' => 'Uma pontuação ponderada igual ou superior a um determinado limiar é classificada nesse intervalo, e uma pontuação abaixo do limiar Moderado é considerada Baixa. A faixa Moderada deve começar acima do valor Baixo, e a faixa Alta deve começar acima da faixa Moderada e não ultrapassar o valor Alto.',
    'ModerateStartsAt' => 'O nível moderado começa em',
    'HighStartsAt' => 'Alto começa em',
    'DefaultScoringForNewAssets' => 'Pontuação padrão para novos ativos',
    'AssetScoringDefaultsHint' => 'Estas classificações são pré-selecionadas quando alguém adiciona um ativo no formulário de ativos. Os ativos criados através de descoberta, importação ou API permanecem sem classificação, a menos que forneçam as suas próprias classificações. Deixe as três opções como "Não definido" para desativar esta função.',
    'AssetScoringWeightsInvalid' => 'Os pesos de pontuação dos ativos devem ser números de 0 a 100 com um máximo de duas casas decimais, e a Integridade e a Disponibilidade não podem ser ambas iguais a 0.',
    'AssetScoringValuesInvalid' => 'Os valores de nível da pontuação de ativos têm de ser números superiores a 0 e até 100 com no máximo duas casas decimais, sendo Baixo inferior a Moderado e Moderado inferior a Alto.',
    'AssetScoringThresholdsInvalid' => 'Os limiares das faixas da pontuação de ativos devem ter no máximo duas casas decimais, com o Moderado a começar acima do valor Baixo, o Alto a começar acima do Moderado, e o Alto a começar não acima do valor Alto.',
