    'AssetScoringResultHelpLabel' => 'Explicação de {$result}',
    'AssetScoringScoreHelp' => 'A pontuação ponderada combina as três classificações num único número entre {$low} e {$high}. Cada classificação passa a ser o respetivo valor definido, e cada um é multiplicado pela ponderação do seu objetivo. Os resultados são somados e divididos pelo total das ponderações. Uma Confidencialidade Não aplicável é excluída, juntamente com a sua ponderação. Os valores definidos e as ponderações são configurados em Preferências. Os três objetivos têm de ser classificados antes de ser apresentada uma pontuação.',
    'AssetScoringCategorizationHelp' => 'A categorização de segurança FIPS 199 corresponde ao valor máximo: a classificação mais elevada entre os objetivos aplicáveis. Uma única classificação Alta torna o ativo Alto, independentemente das restantes. Não aplicável é ignorado.',
    'AssetScoringBandHelp' => 'A faixa posiciona a pontuação ponderada numa escala Baixa, Moderada ou Alta. Uma pontuação inferior a {$moderate} é Baixa, de {$moderate} até {$highAt} é Moderada, e {$highAt} ou mais é Alta. Os limiares são configurados em Preferências.',
